        category = LocalizedText("""Novenas""", """Novenas""", """Novenas"""),
        description = LocalizedText("""Recordatorios diarios + intenciones + oraciones grupales""", """Daily reminders + prayer intentions + group prayers""", """Santo padroeiro de a Jordânia, Porto Rico, a Ordem de Malta (Cavaleiros Hospitalários de São João), Quebec, Terra Nova, Cesena, Florença, Gênova, Monza, Perth (Escócia), Porto, San Juan, Turim, Xewkija"""),
